<?php
require_once __DIR__ . '/includes/automatic-results-schema.php';
$token = trim((string)($_GET['token'] ?? ''));
if ($token === '' || !preg_match('/^[a-f0-9]{64}$/', $token)) { http_response_code(404); exit('Result not found.'); }
$st = $pdo->prepare("SELECT rr.*, u.email, u.phone FROM result_requests rr LEFT JOIN users u ON u.id=rr.user_id WHERE rr.result_access_token=? AND rr.status='completed' LIMIT 1");
$st->execute([$token]);
$r = $st->fetch();
if (!$r || empty($r['result_payload'])) { http_response_code(404); exit('Result not available.'); }
$payload = json_decode((string)$r['result_payload'], true);
if (!is_array($payload)) { http_response_code(500); exit('Stored result is invalid.'); }
$result = $payload['data'] ?? $payload;
function rv_h($v){ return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
