rv_h(json_encode($result['overall'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)); ?></pre></div><?php endif; ?><p style="margin-top:20px;color:#777;font-size:12px">For official verification, use the WAEC Ghana results/verification service.</p></div></div></main><?php include __DIR__ . '/includes/footer.php'; ?>
